async function loadCoinOrders(){const r=await db.rpc('spike_my_coin_orders');if(r.error)throw r.error;const rows=r.data||[];const packageIds=[...new Set(rows.map(o=>o.package_id).filter(Boolean))];let packageNames={};if(packageIds.length){const p=await db.from('coin_packages').select('id,name').in('id',packageIds);if(p.error)throw p.error;for(const item of p.data||[])packageNames[item.id]=item.name}$('coinOrders').innerHTML=rows.length?`<div class="wallet-table-wrap"><table class="wallet-table"><thead><tr><th>Reference</th><th>SP Coins</th><th>Amount</th><th>Status</th><th>Created</th><th>Next step</th></tr></thead><tbody>${rows.map(o=>{let next='—';if(o.status==='pending'){try{next=`<a class="wallet-wa" target="_blank" rel="noopener" href="${esc(purchaseWaLink(o,packageNames[o.package_id]))}">WhatsApp SPIKE</a>`}catch(_){next='<span class="wallet-muted">Purchase details unavailable; reload Wallet</span>'}}else if(o.status==='payment_reported')next='Awaiting Owner verification';else if(o.status==='approved')next='Coins credited';else if(o.status==='rejected')next=esc(o.rejection_reason||'Rejected');else if(o.status==='cancelled')next=esc(o.cancellation_reason||'Cancelled');const canCancel=['pending','payment_reported'].includes(o.status);return `<tr><td><strong>${esc(o.reference)}</strong></td><td><strong>${(Number(o.coins)||0)+(Number(o.bonus_coins)||0)} SP</strong><small class="wallet-order-breakdown">${Number(o.coins||0).toLocaleString('en-NG')} base + ${Number(o.bonus_coins||0).toLocaleString('en-NG')} bonus</small></td><td>${money(o.amount_minor,o.currency)}</td><td><span class="wallet-chip">${esc(o.status)}</span></td><td>${esc(new Date(o.created_at).toLocaleString())}</td><td>${next}${canCancel?`<div style="margin-top:8px"><button class="wallet-action wallet-cancel-order" type="button" data-cancel-coin-order="${esc(o.id)}" data-order-status="${esc(o.status)}" style="background:#a83245">Cancel request</button></div>`:''}</td></tr>${o.status==='pending'?`<tr><td colspan="6"><form class="wallet-row" data-payment-report="${esc(o.id)}" data-order-reference="${esc(o.reference)}"><label class="wallet-field">Bank transfer reference<input name="payment_reference" required maxlength="120" autocomplete="off" placeholder="Enter reference from your bank receipt"><small class="wallet-muted">Use the transaction reference generated by your bank — not this SPIKE purchase reference: ${esc(o.reference)}</small></label><button class="wallet-action" type="button" data-payment-report-submit>I have transferred</button></form></td></tr>`:''}`}).join('')}</tbody></table></div>`:'<p class="wallet-muted">You have not created an SP Coin purchase yet.</p>'; }function formatCreatorUsd(value){const n=Math.max(0,Number(value)||0);return new Intl.NumberFormat('en-US',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:8}).format(n)}
