function renderCreatorProgress(availableNgn){const targets=[5000,6000,7000,8000,9000,10000];const amount=Math.max(0,Number(availableNgn)||0);const pct=Math.min(100,Math.max(0,(amount-5000)/5000*100));const next=targets.find(target=>amount<target);const reached=targets.filter(target=>amount>=target).length;const remaining=next?Math.max(0,next-amount):0;return `<div class="creator-progress-title"><span>Withdrawal earnings milestones</span><small>₦5,000–₦10,000</small></div><div class="creator-progress-current"><span>Net creator earnings</span><strong>${formatCreatorNgn(amount)}</strong></div><div class="creator-progress-track" role="progressbar" aria-label="Withdrawal earnings progress from ₦5,000 to ₦10,000" aria-valuemin="5000" aria-valuemax="10000" aria-valuenow="${Math.min(10000,Math.max(5000,amount))}"><span style="width:${pct.toFixed(2)}%"></span></div><div class="creator-progress-labels">${targets.map(target=>`<span class="creator-progress-label${amount>=target?' is-hit':''}">${amount>=target?'✓ ':''}₦${target.toLocaleString('en-NG')}</span>`).join('')}</div><div class="creator-progress-foot"><span>${reached} of 6 milestones reached</span><strong>${next?`${formatCreatorNgn(remaining)} to next milestone`:'All milestones reached'}</strong></div>`}
